const $=s=>document.querySelector(s), token=()=>sessionStorage.getItem("maxio_token");
async function api(path,options={}){const headers={...(options.headers||{}),...(token()?{Authorization:`Bearer ${token()}`}:{})};const r=await fetch(path,{...options,headers});const body=await r.json().catch(()=>({}));if(!r.ok)throw Error(body.detail||"No pudimos completar la solicitud.");return body}
const empty="<span class=empty>Sin información todavía.</span>", date=v=>new Intl.DateTimeFormat("es-UY",{day:"2-digit",month:"short",year:"numeric"}).format(new Date(v));
const html=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
function matchDetails(match){const names=items=>items.length?items.map(player=>`<a class="match-player" href="/web/player.html?username=${encodeURIComponent(player.name)}">${html(player.name)}</a>`).join(""):"<span class=empty>Ninguno</span>";return `<div class="match-details"><div class="match-meta"><span>Partido</span><b>#${match.match_id}</b><span>Fecha</span><b>${date(match.date)}</b><span>Tu lado</span><b>${match.team||"Sin equipo"}</b></div><div><h4>Compañeros</h4><p>${names(match.teammates)}</p></div><div><h4>Oponentes</h4><p>${names(match.opponents)}</p></div></div>`}
function profile(p){$("#name").textContent=p.name;$("#elo").textContent=`ELO ${p.stats.elo}`;$("#played").textContent=p.matches_summary.played;$("#won").textContent=p.matches_summary.won;$("#winrate").textContent=`${p.matches_summary.winrate}%`;
const labels={tiro:"Tiro",ritmo:"Ritmo",fisico:"Físico",defensa:"Defensa",aura:"Aura"};$("#stats").innerHTML=Object.entries(labels).map(([k,n])=>`<article class=stat><div><span>${n}</span><b>${Math.round(p.stats[k])}</b></div><div class=meter><i style="width:${p.stats[k]}%"></i></div></article>`).join("");
$("#form").innerHTML=p.matches_summary.recent_results.length?p.matches_summary.recent_results.map(x=>`<span class="dot ${x?"win":"loss"}">${x?"V":"D"}</span>`).join("")+`<span class=empty>${p.matches_summary.recent_results.filter(Boolean).length} victorias recientes</span>`:empty;
const recentMatches=p.recent_matches.slice(0,3);$("#matches").innerHTML=recentMatches.length?recentMatches.map((m,index)=>`<article class="match ${m.result}" data-match-index="${index}" tabindex="0" role="button" aria-expanded="false"><span class="pill ${m.result}">${({win:"Ganado",loss:"Perdido",pending:"Pendiente"})[m.result]}</span><div><b>Partido #${m.match_id}</b><p>Con ${m.teammates.map(x=>html(x.name)).join(", ")||"sin compañeros"}</p></div><time>${date(m.date)}</time><span class="match-chevron">⌄</span><div class="match-detail-slot"></div></article>`).join(""):empty;$("#matches").querySelectorAll(".match").forEach((row,index)=>{const toggle=()=>{const slot=row.querySelector(".match-detail-slot");const open=!!slot.innerHTML;slot.innerHTML=open?"":matchDetails(recentMatches[index]);row.classList.toggle("expanded",!open);row.setAttribute("aria-expanded",String(!open))};row.addEventListener("click",event=>{if(!event.target.closest(".match-details"))toggle()});row.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();toggle()}})});
const groups=[["Más partidos","most_played_with"],["Mejores aliados","top_allies"],["Más enfrentados","top_opponents"]];$("#relations").innerHTML=groups.map(([n,k])=>`<article class=relation><h3>${n}</h3>${p.relations[k].length?p.relations[k].map(x=>`<span class=chip>${x.name}</span>`).join(""):empty}</article>`).join("");}
async function linkTelegram(){const initData=window.Telegram?.WebApp?.initData;if(!initData||!token())return;try{await api("/maxio/users/telegram/link",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({init_data:initData})})}catch(error){console.warn("No se pudo vincular Telegram:",error.message)}}
async function restoreTelegramSession(){const initData=window.Telegram?.WebApp?.initData;if(!initData)return false;try{const response=await fetch("/auth/telegram/webapp",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({init_data:initData})});if(!response.ok)return false;const session=await response.json();sessionStorage.setItem("maxio_token",session.access_token);return true}catch(error){console.warn("No se pudo restaurar la sesión de Telegram:",error.message);return false}}
async function dashboard(){$("#login").hidden=true;$("#dashboard").hidden=false;$("#loading").hidden=false;$("#content").hidden=true;try{const u=await api("/maxio/users/me");if(u.is_admin){window.location.replace("/web/admin");return}const p=await api(`/player/${encodeURIComponent(u.username)}/profile`);profile(p);$("#content").hidden=false}catch(e){sessionStorage.removeItem("maxio_token");document.documentElement.classList.remove("has-session");$("#dashboard").hidden=true;$("#login").hidden=false;$("#error").textContent=e.message}finally{$("#loading").hidden=true}}
$("#login-form").addEventListener("submit",async e=>{e.preventDefault();$("#error").textContent="";const d=new FormData(e.target);try{const r=await fetch("/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:d.get("username"),password:d.get("password")})}),b=await r.json();if(!r.ok)throw Error(b.detail||"No pudimos ingresar.");sessionStorage.setItem("maxio_token",b.access_token);await linkTelegram();dashboard()}catch(x){$("#error").textContent=x.message}});$("#logout").onclick=()=>{if(!window.confirm("¿Realmente querés cerrar sesión?"))return;sessionStorage.removeItem("maxio_token");document.documentElement.classList.remove("has-session");$("#dashboard").hidden=true;$("#login").hidden=false};async function bootDashboard(){if(token()){await linkTelegram();await dashboard();if(token())return}if(await restoreTelegramSession())await dashboard()}bootDashboard();
