  registerToggle.addEventListener("click",()=>toggleAuth(true));registerForm.querySelector("[data-back-login]").addEventListener("click",()=>toggleAuth(false));
  registerForm.addEventListener("submit",async event=>{event.preventDefault();const button=registerForm.querySelector("button:not([data-back-login])"),error=$("#register-error");error.textContent="";button.disabled=true;const data=Object.fromEntries(new FormData(registerForm));data.nationality=(data.nationality||"UY").trim().toUpperCase();data.is_bot=false;try{const response=await fetch("/maxio/users/register",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)}),body=await response.json().catch(()=>({}));if(!response.ok)throw Error(body.detail||"No se pudo crear la cuenta.");const loginResponse=await fetch("/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:data.username,password:data.password})}),loginBody=await loginResponse.json().catch(()=>({}));if(!loginResponse.ok)throw Error(loginBody.detail||"La cuenta fue creada, pero no se pudo iniciar sesión.");sessionStorage.setItem("maxio_token",loginBody.access_token);await linkTelegram();toggleAuth(false);await dashboard()}catch(errorValue){error.textContent=errorValue.message}finally{button.disabled=false}});
