// Presentación renovada del historial y respuestas compartidas con Telegram.
const matchHistoryStyle=document.createElement("style");matchHistoryStyle.textContent=`.match-details{display:grid;gap:10px}.match-date-main{font-size:13px;font-weight:800;color:var(--lime)}.match-party h4{margin:0 0 5px}.match-player{display:inline-flex;align-items:center;gap:6px}.response-state{font-size:10px;color:var(--muted);font-weight:600}.response-state.win{color:#5be092}.response-state.loss{color:#ff8290}.response-state.bot{color:#b7c4d8}.match-outcome{display:flex;flex-wrap:wrap;align-items:center;gap:7px;padding-top:4px}.match-outcome.resolved{color:var(--muted)}.match-answer{border:1px solid #35c978;border-radius:8px;background:#173e34;color:#b9ffd2;padding:6px 10px;font-weight:700}.match-answer.loss{border-color:#f05b68;background:#482832;color:#ffd1d5}`;document.head.append(matchHistoryStyle);
const matchDateTime=value=>new Intl.DateTimeFormat("es-UY",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(value));
const matchResponseLabel=response=>({win:"Dijo que ganó",loss:"Dijo que perdió",pending:"Sin responder",bot:"Bot"}[response]||"Sin respuesta");
function matchDetails(match){const names=items=>items.length?items.map(player=>`<a class="match-player" href="/web/player.html?username=${encodeURIComponent(player.name)}"><span>${html(player.name)}</span><small class="response-state ${player.response||"pending"}">${matchResponseLabel(player.response)}</small></a>`).join(""):"<span class=empty>Ninguno</span>";const passed=new Date(match.date)<=new Date();let answer;if(match.result!=="pending")answer=`<div class="match-outcome resolved">Resultado: <b>${match.result==="win"?"Ganaste":"Perdiste"}</b></div>`;else if(!passed)answer="<div class=match-outcome>El partido todavía no está disponible para responder.</div>";else if(match.my_response==="pending")answer="<div class=match-outcome><span>¿Ganaste o perdiste?</span><button type=button class=match-answer data-match-result=win>Gané</button><button type=button class=\"match-answer loss\" data-match-result=loss>Perdí</button></div>";else answer=`<div class="match-outcome resolved">Respondido: <b>${matchResponseLabel(match.my_response).replace("Dijo que ","")}</b></div>`;return `<div class=match-details><div class=match-date-main>${matchDateTime(match.date)}</div><div class=match-party><h4>Mi equipo</h4><p>${names(match.teammates)}</p></div><div class=match-party><h4>Rivales</h4><p>${names(match.opponents)}</p></div>${answer}</div>`}
function profile(p){$("#name").textContent=p.name;$("#elo").textContent=`ELO ${p.stats.elo}`;$("#played").textContent=p.matches_summary.played;$("#won").textContent=p.matches_summary.won;$("#winrate").textContent=`${p.matches_summary.winrate}%`;const labels={tiro:"Tiro",ritmo:"Ritmo",fisico:"Físico",defensa:"Defensa",aura:"Aura"};$("#stats").innerHTML=Object.entries(labels).map(([k,n])=>`<article class=stat><div><span>${n}</span><b>${Math.round(p.stats[k])}</b></div><div class=meter><i style="width:${p.stats[k]}%"></i></div></article>`).join("");$("#form").innerHTML=p.matches_summary.recent_results.length?p.matches_summary.recent_results.map(x=>`<span class="dot ${x?"win":"loss"}">${x?"V":"D"}</span>`).join("")+`<span class=empty>${p.matches_summary.recent_results.filter(Boolean).length} victorias recientes</span>`:empty;const recent=p.recent_matches.slice(0,3);$("#matches").innerHTML=recent.length?recent.map((m,i)=>`<article class="match ${m.result}" tabindex=0 role=button aria-expanded=false><span class="pill ${m.result}">${({win:"Ganado",loss:"Perdido",pending:"Pendiente"})[m.result]}</span><div><b>${matchDateTime(m.date)}</b><p>${m.teammates.map(x=>html(x.name)).join(", ")||"sin compañeros"}</p></div><span class=match-chevron>⌄</span><div class=match-detail-slot></div></article>`).join(""):empty;$("#matches").querySelectorAll(".match").forEach((row,i)=>{const toggle=()=>{const slot=row.querySelector(".match-detail-slot"),open=!!slot.innerHTML;slot.innerHTML=open?"":matchDetails(recent[i]);row.classList.toggle("expanded",!open);row.setAttribute("aria-expanded",String(!open));if(!open)row.querySelectorAll("[data-match-result]").forEach(button=>button.addEventListener("click",async event=>{event.stopPropagation();button.disabled=true;try{await api(`/match/matches/${recent[i].match_id}/result`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({result:button.dataset.matchResult})});await dashboard()}catch(error){button.disabled=false;alert(error.message)}}))};row.addEventListener("click",event=>{if(!event.target.closest(".match-details"))toggle()});row.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();toggle()}})});const groups=[["Más partidos","most_played_with"],["Mejores aliados","top_allies"],["Más enfrentados","top_opponents"]];$("#relations").innerHTML=groups.map(([n,k])=>`<article class=relation><h3>${n}</h3>${p.relations[k].length?p.relations[k].map(x=>`<span class=chip>${html(x.name)}</span>`).join(""):empty}</article>`).join("")}

