const matchIconStyle=document.createElement("style");matchIconStyle.textContent=`.match-compact-date{font-weight:800;color:var(--ink)}.match-response-mark{display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;font-size:18px;font-weight:900;line-height:1}.match-response-mark.win{color:#35c978}.match-response-mark.loss{color:#f05b68}.match-response-mark.pending,.match-response-mark.bot{color:#5da9e9}`;document.head.append(matchIconStyle);
const matchResponseMark=response=>response==="win"?"✓":response==="loss"?"×":"–";
function matchDetails(match){const names=items=>items.length?items.map(player=>{const response=player.response||"pending";return `<a class="match-player" href="/web/player.html?username=${encodeURIComponent(player.name)}"><span>${html(player.name)}</span><span class="match-response-mark ${response}" title="${response==="win"?"Votó que ganó":response==="loss"?"Votó que perdió":response==="bot"?"Bot":"No votó"}" aria-label="${response==="win"?"Votó que ganó":response==="loss"?"Votó que perdió":response==="bot"?"Bot":"No votó"}">${matchResponseMark(response)}</span></a>`}).join(""):"<span class=empty>Ninguno</span>";const passed=new Date(match.date)<=new Date();let answer;if(match.result!=="pending")answer=`<div class="match-outcome resolved">Resultado: <b>${match.result==="win"?"Ganaste":"Perdiste"}</b></div>`;else if(!passed)answer="<div class=match-outcome>El partido todavía no está disponible para responder.</div>";else if(match.my_response==="pending")answer="<div class=match-outcome><span>¿Ganaste o perdiste?</span><button type=button class=match-answer data-match-result=win>Gané</button><button type=button class=\"match-answer loss\" data-match-result=loss>Perdí</button></div>";else answer=`<div class="match-outcome resolved">Respondido: <span class="match-response-mark ${match.my_response}" aria-label="${matchResponseMark(match.my_response)}">${matchResponseMark(match.my_response)}</span></div>`;return `<div class=match-details><div class=match-date-main>${matchDateTime(match.date)}</div><div class=match-party><h4>Mi equipo</h4><p>${names(match.teammates)}</p></div><div class=match-party><h4>Rivales</h4><p>${names(match.opponents)}</p></div>${answer}</div>`}
function profile(p){$("#name").textContent=p.name;$("#elo").textContent=`ELO ${p.stats.elo}`;$("#played").textContent=p.matches_summary.played;$("#won").textContent=p.matches_summary.won;$("#winrate").textContent=`${p.matches_summary.winrate}%`;const labels={tiro:"Tiro",ritmo:"Ritmo",fisico:"Físico",defensa:"Defensa",aura:"Aura"};$("#stats").innerHTML=Object.entries(labels).map(([k,n])=>`<article class=stat><div><span>${n}</span><b>${Math.round(p.stats[k])}</b></div><div class=meter><i style="width:${p.stats[k]}%"></i></div></article>`).join("");$("#form").innerHTML=p.matches_summary.recent_results.length?p.matches_summary.recent_results.map(x=>`<span class="dot ${x?"win":"loss"}">${x?"V":"D"}</span>`).join("")+`<span class=empty>${p.matches_summary.recent_results.filter(Boolean).length} victorias recientes</span>`:empty;const recent=p.recent_matches.slice(0,3);$("#matches").innerHTML=recent.length?recent.map((m,i)=>`<article class="match ${m.result}" tabindex=0 role=button aria-expanded=false><div><b class=match-compact-date>${matchDateTime(m.date)}</b></div><span class="pill ${m.result}">${({win:"Ganado",loss:"Perdido",pending:"Pendiente"})[m.result]}</span><span class=match-chevron>⌄</span><div class=match-detail-slot></div></article>`).join(""):empty;$("#matches").querySelectorAll(".match").forEach((row,i)=>{const toggle=()=>{const slot=row.querySelector(".match-detail-slot"),open=!!slot.innerHTML;slot.innerHTML=open?"":matchDetails(recent[i]);row.classList.toggle("expanded",!open);row.setAttribute("aria-expanded",String(!open));if(!open)row.querySelectorAll("[data-match-result]").forEach(button=>button.addEventListener("click",async event=>{event.stopPropagation();button.disabled=true;try{await api(`/match/matches/${recent[i].match_id}/result`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({result:button.dataset.matchResult})});await dashboard()}catch(error){button.disabled=false;alert(error.message)}}))};row.addEventListener("click",event=>{if(!event.target.closest(".match-details"))toggle()});row.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();toggle()}})});const groups=[["Más partidos","most_played_with"],["Mejores aliados","top_allies"],["Más enfrentados","top_opponents"]];$("#relations").innerHTML=groups.map(([n,k])=>`<article class=relation><h3>${n}</h3>${p.relations[k].length?p.relations[k].map(x=>`<span class=chip>${html(x.name)}</span>`).join(""):empty}</article>`).join("")}

// Historial de relaciones: tres áreas con jerarquía, avatar y volumen de partidos.
const relationHistoryStyle=document.createElement("style");relationHistoryStyle.textContent=`.relations.relations-showcase{display:grid;grid-template-columns:1fr;gap:14px}.relations-showcase .relation{position:relative;overflow:hidden;padding:20px;border-radius:20px;background:linear-gradient(135deg,#142a47,#0f1b2d);border-color:#365477}.relations-showcase .relation::after{content:"";position:absolute;width:150px;height:150px;right:-55px;top:-65px;border-radius:50%;background:#70b5ff18}.relations-showcase .relation.featured{background:linear-gradient(135deg,#253f29,#102b2b);border-color:#709b55}.relations-showcase .relation.rivals{background:linear-gradient(135deg,#3a2430,#181c31);border-color:#754b5d}.relation-heading{position:relative;z-index:1;display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:16px}.relation-heading h3{margin:2px 0 0;font-size:17px;letter-spacing:-.3px}.relation-kicker{font-size:9px;letter-spacing:1.2px;color:var(--lime);font-weight:900;text-transform:uppercase}.relation-description{margin:0;color:var(--muted);font-size:11px;line-height:1.4;max-width:310px}.relation-ranking{display:grid;gap:8px;position:relative;z-index:1}.relation-player{display:flex!important;align-items:center;gap:11px;width:100%;margin:0!important;padding:9px 10px!important;border:1px solid #ffffff18!important;border-radius:14px!important;background:#08152566!important;color:var(--ink)!important;text-decoration:none;box-shadow:none!important}.relation-player:hover{border-color:var(--lime)!important;transform:translateY(-1px)}.relation-rank{width:24px;text-align:center;color:var(--muted);font-size:12px;font-weight:900}.relation-player:first-child .relation-rank{color:var(--lime);font-size:16px}.relation-player img{width:42px;height:42px;object-fit:cover;border-radius:13px;background:#203551}.relation-player-info{display:grid;gap:3px;min-width:0;text-align:left}.relation-player-name{font-size:13px;font-weight:850;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.relation-player-meta{font-size:10px;color:var(--muted)}.relation-player-count{margin-left:auto;display:grid;justify-items:end;gap:1px}.relation-player-count b{font-size:18px;color:var(--lime)}.relation-player-count span{font-size:9px;color:var(--muted)}.relation-empty{position:relative;z-index:1;padding:14px;border:1px dashed #ffffff2c;border-radius:12px;color:var(--muted);font-size:12px}@media(min-width:700px){.relations.relations-showcase{grid-template-columns:1.15fr 1fr 1fr}.relations-showcase .relation{min-height:230px}}`;document.head.append(relationHistoryStyle);
function renderRelationShowcase(profileData){const configs=[{key:"most_played_with",title:"Los de siempre",kicker:"CONEXIÓN PRINCIPAL",description:"Los jugadores con los que más veces compartiste equipo.",metric:"total_games",theme:"featured"},{key:"top_allies",title:"Tus aliados",kicker:"JUEGO EN EQUIPO",description:"Compañeros que más veces estuvieron de tu lado.",metric:"games_together",theme:""},{key:"top_opponents",title:"Rivales conocidos",kicker:"HISTORIAL EN CONTRA",description:"Los rivales que más veces enfrentaste.",metric:"games_apart",theme:"rivals"}];$("#relations").className="relations relations-showcase";$("#relations").innerHTML=configs.map(config=>{const players=profileData.relations[config.key]||[];return `<article class="relation ${config.theme}"><div class=relation-heading><div><span class=relation-kicker>${config.kicker}</span><h3>${config.title}</h3></div><span class=relation-kicker>${players.length?`${players.length} destacados`:""}</span></div><p class=relation-description>${config.description}</p><div class=relation-ranking>${players.length?players.map((player,index)=>`<a class="chip relation-player" data-player="${html(player.name)}" href="/web/player.html?username=${encodeURIComponent(player.name)}"><span class=relation-rank>${index===0?"★":String(index+1).padStart(2,"0")}</span><img src="/player/${encodeURIComponent(player.name)}/photo" alt=""><span class=relation-player-info><span class=relation-player-name>${html(player.name)}</span><span class=relation-player-meta>Perfil y estadísticas</span></span><span class=relation-player-count><b>${player[config.metric]||0}</b><span>partidos</span></span></a>`).join(""):"<div class=relation-empty>Aún no hay suficientes partidos para mostrar conexiones.</div>"}</div></article>`}).join("")}
