function renderRelationShowcaseFixed(profileData){const configs=[{key:"most_played_with",title:"Los de siempre",kicker:"CONEXIÓN PRINCIPAL",description:"Los jugadores con los que más veces compartiste equipo.",metric:"total_games",theme:"featured"},{key:"top_allies",title:"Tus aliados",kicker:"JUEGO EN EQUIPO",description:"Compañeros que más veces estuvieron de tu lado.",metric:"games_together",theme:""},{key:"top_opponents",title:"Rivales conocidos",kicker:"HISTORIAL EN CONTRA",description:"Los rivales que más veces enfrentaste.",metric:"games_apart",theme:"rivals"}];const root=$("#relations");root.className="relations relations-showcase";root.innerHTML=configs.map(config=>{const players=profileData.relations[config.key]||[];const rows=players.length?players.map((player,index)=>{const name=html(player.name);return `<a href="/web/player.html?username=${encodeURIComponent(player.name)}" class="relation-player chip" data-player="${name}" aria-label="Ver perfil de ${name}"><span class="relation-rank">${index===0?"★":String(index+1).padStart(2,"0")}</span><img src="/player/${encodeURIComponent(player.name)}/photo" alt="Avatar de ${name}"><span class="relation-player-info"><span class="relation-player-name">${name}</span><span class="relation-player-meta">Ver perfil y estadísticas</span></span><span class="relation-player-count"><b>${player[config.metric]||0}</b><span>partidos</span></span></a>`}).join(""):"<div class=relation-empty>Aún no hay suficientes partidos para mostrar conexiones.</div>";return `<article class="relation ${config.theme}"><div class=relation-heading><div><span class=relation-kicker>${config.kicker}</span><h3>${config.title}</h3></div><span class=relation-kicker>${players.length?`${players.length} destacados`:""}</span></div><p class=relation-description>${config.description}</p><div class=relation-ranking>${rows}</div></article>`}).join("")}
