// La liga nacional es obligatoria: se identifica visualmente y no ofrece salida.
const nationalLeagueUiGuard=new MutationObserver(()=>{document.querySelectorAll(".league-card-ui").forEach(card=>{const title=card.querySelector("h4"),name=title?.textContent.trim();if(!["Liga Uruguay","UY 🇺🇾"].includes(name)||card.dataset.nationalLeague)return;card.dataset.nationalLeague="true";card.querySelector(".leave")?.remove();const badges=card.querySelector(".league-badges");if(badges)badges.insertAdjacentHTML("beforeend",'<span class="league-badge public">NACIONAL</span>')})});
nationalLeagueUiGuard.observe(document.body,{childList:true,subtree:true});

// OVR replica el promedio que se muestra en la tarjeta del jugador. Se agrega
// después del renderizador base para no duplicar reglas de cálculo en la API.
const profileWithOverall=profile;
profile=function(player){
  profileWithOverall(player);
  const values=["tiro","ritmo","fisico","defensa","aura"]
    .map(key=>Number(player.stats?.[key]))
    .filter(Number.isFinite);
  if(values.length!==5)return;
  const overall=Math.round(values.reduce((total,value)=>total+value,0)/values.length);
  const statsContainer=$("#stats");
  if(!statsContainer)return;
  statsContainer.querySelector(".stat-overall")?.remove();
  statsContainer.insertAdjacentHTML("beforeend",`<article class="stat stat-overall" aria-label="Overall ${overall}"><div><span>OVR <small>promedio</small></span><b>${overall}</b></div><div class="meter"><i style="width:${Math.max(0,Math.min(100,overall))}%"></i></div></article>`);
};
const overallStatStyle=document.createElement("style");
overallStatStyle.textContent=`#stats .stat-overall{border-color:#8470c9;background:linear-gradient(135deg,#25244d,#192e4c);box-shadow:inset 0 1px #d9d0ff22}#stats .stat-overall>div:first-child span{color:#cfc5ff}#stats .stat-overall small{min-height:0;margin-left:4px;color:#a99de0;font-size:9px;font-weight:700;letter-spacing:.25px}#stats .stat-overall b{color:#eeeaff}#stats .stat-overall .meter{background:#312d5b}#stats .stat-overall .meter i{background:linear-gradient(90deg,#8f7cff,#b9a9ff)}@media(min-width:700px){#stats.stats{grid-template-columns:repeat(2,1fr)}}`;
document.head.append(overallStatStyle);

